@router.patch("/knowledge/articles/{article_id}/access-policy")
async def update_article_access_policy(
    article_id: PydanticObjectId,
    policy: AccessPolicyUpdateSchema,
    current_user: User = Depends(get_current_user)
):
    article = await KnowledgeArticle.get(article_id)
    if not article:
        raise HTTPException(status_code=404, detail="Article not found")

    if article.author_id != current_user.id and current_user.role != "KB_ADMIN":
        raise HTTPException(status_code=403, detail="Forbidden: only authors or KB admins can modify access policies")

    await article.update(
        Set({
            KnowledgeArticle.allowed_groups: policy.allowed_groups,
            KnowledgeArticle.is_confidential: policy.is_confidential,
            KnowledgeArticle.public_preview: policy.public_preview
        })
    )
    return {"status": "policy_updated", "article_id": str(article.id)}
